		if (!vsi->q_vectors[v_idx])
			continue;

		q_vector = vsi->q_vectors[v_idx];
		if (!q_vector)
			continue;

		for (q_idx = 0; q_idx < q_vector->num_rx_queues; q_idx++) {
			struct ice_q_vector *rx_vec = &q_vector->rx_rings[q_idx];
			if (rx_vec->netdev_queue)
				napi_enable(&rx_vec->napi);
		}

		for (q_idx = 0; q_idx < q_vector->num_tx_queues; q_idx++) {
			struct ice_q_vector *tx_vec = &q_vector->tx_rings[q_idx];
			if (tx_vec->netdev_queue)
				napi_enable(&tx_vec->napi);
		}
	}

